insert into public.problem_catalog(id,document) values
('alg-f01','{"id":"alg-f01","title":"The Hidden Pair","topic":"Algebra","level":"Foundation","question":"A positive real $x$ satisfies $x+1/x=3$. Find $x^2+1/x^2$.","type":"text","correctAnswer":"7","hint":"Square the given reciprocal sum and subtract the middle term.","solution":"Squaring gives $x^2+2+x^{-2}=9$, so $x^2+x^{-2}=7$.","points":31,"competition":"AMC","answerMode":"choice","maxAttempts":3,"estimatedSteps":2,"abstraction":1,"options":["4","6","7","9","12"]}'::jsonb),
('alg-a01','{"id":"alg-a01","title":"A Recurrence in Disguise","topic":"Algebra","level":"Advanced","question":"Let $r$ and $s$ be the roots of $t^2 - 7t + 1 = 0$. Find the remainder when $r^6 + s^6$ is divided by $1000$.","type":"text","correctAnswer":"682","hint":"If $S_n=r^n+s^n$, use $r+s=7$, $rs=1$, and the recurrence $S_n=7S_{n-1}-S_{n-2}$.","solution":"Set $S_n=r^n+s^n$. Since each root satisfies $t^2=7t-1$, we have $S_n=7S_{n-1}-S_{n-2}$ with $S_0=2$ and $S_1=7$. This gives $S_2=47$, $S_3=322$, $S_4=2207$, $S_5=15127$, and $S_6=103682$. Therefore the requested remainder is $682$.","points":60,"competition":"AIME","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3}'::jsonb),
('alg-o01','{"id":"alg-o01","title":"Power Sums Without Solving","topic":"Algebra","level":"Olympiad","question":"A positive real number $x$ satisfies $x + \\frac{1}{x} = 3$. Find the last three digits of $\\left(x^5 + \\frac{1}{x^5}\\right)^2$.","type":"text","correctAnswer":"129","hint":"Let $T_n=x^n+x^{-n}$. The relation $x+x^{-1}=3$ gives $T_n=3T_{n-1}-T_{n-2}$.","solution":"With $T_0=2$ and $T_1=3$, the recurrence $T_n=3T_{n-1}-T_{n-2}$ gives $T_2=7$, $T_3=18$, $T_4=47$, and $T_5=123$. Thus $T_5^2=123^2=15129$, whose last three digits are $129$.","points":79,"competition":"AIME","answerMode":"numeric-grid","proOnly":false,"maxAttempts":3,"estimatedSteps":5,"abstraction":5,"answerDigits":3}'::jsonb),
('geo-f01','{"id":"geo-f01","title":"Heron in One Move","topic":"Geometry","level":"Foundation","question":"A triangle has side lengths $13$, $14$, and $15$. If $K$ is its area and $r$ is its inradius, find $K+r^2$.","type":"text","correctAnswer":"100","hint":"Use Heron''s formula with semiperimeter $21$, then use $r=K/s$.","solution":"The semiperimeter is $s=21$. Heron''s formula gives $K=\\sqrt{21\\cdot8\\cdot7\\cdot6}=84$. Therefore $r=K/s=84/21=4$, and $K+r^2=84+16=100$.","points":46,"competition":"AMC","answerMode":"choice","maxAttempts":3,"estimatedSteps":3,"abstraction":2,"figure":{"kind":"triangle","labels":["13","14","15"],"values":[13,14,15]},"options":["97","99","100","102","105"]}'::jsonb),
('geo-a01','{"id":"geo-a01","title":"A Cyclic Quadrilateral","topic":"Geometry","level":"Advanced","question":"A cyclic quadrilateral has consecutive side lengths $4$, $5$, $6$, and $7$. Find the square of its area.","type":"text","correctAnswer":"840","hint":"Apply Brahmagupta''s formula with semiperimeter $s=11$, and leave the answer squared.","solution":"The semiperimeter is $s=(4+5+6+7)/2=11$. Brahmagupta''s formula gives $K^2=(11-4)(11-5)(11-6)(11-7)=7\\cdot6\\cdot5\\cdot4=840$.","points":55,"competition":"AIME","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":3,"figure":{"kind":"quadrilateral","labels":["4","5","6","7"],"values":[4,5,6,7]}}'::jsonb),
('geo-o01','{"id":"geo-o01","title":"The Distance Between Centers","topic":"Geometry","level":"Olympiad","question":"A triangle has side lengths $10$, $17$, and $21$. Let $O$ and $I$ be its circumcenter and incenter. Write $OI^2$ in lowest terms, and enter the remainder when its numerator is divided by $1000$.","type":"text","correctAnswer":"465","hint":"Heron gives the area and $r$; then use $R=abc/(4K)$ and Euler''s formula $OI^2=R(R-2r)$.","solution":"Here $s=24$ and $K=\\sqrt{24\\cdot14\\cdot7\\cdot3}=84$. Thus $r=K/s=7/2$ and $R=10\\cdot17\\cdot21/(4\\cdot84)=85/8$. Euler''s formula gives $OI^2=(85/8)(85/8-7)=2465/64$. The numerator''s remainder modulo $1000$ is $465$.","points":81,"competition":"AIME","answerMode":"numeric-grid","proOnly":false,"maxAttempts":3,"estimatedSteps":5,"abstraction":5,"figure":{"kind":"triangle","labels":["10","17","21"],"values":[10,17,21],"construction":"centers"},"answerDigits":3}'::jsonb),
('comb-f01','{"id":"comb-f01","title":"Digit Sets and Permutations","topic":"Combinatorics","level":"Foundation","question":"How many four-digit positive integers have four distinct digits and a digit sum divisible by $9$?","type":"text","correctAnswer":"516","hint":"First choose the four-digit set. A set containing $0$ has only $4!-3!$ valid arrangements; a set without $0$ has $4!$.","solution":"The generating polynomial $\\prod_{d=0}^{9}(1+t z^d)$ shows that $24$ four-digit sets have digit sum $0$ modulo $9$: $14$ contain no zero and $10$ contain zero. The first type contributes $14\\cdot4!=336$ numbers; the second contributes $10\\cdot(4!-3!)=180$. The total is $336+180=516$.","points":70,"competition":"AMC","answerMode":"choice","maxAttempts":3,"estimatedSteps":5,"abstraction":4,"options":["513","515","516","518","521"]}'::jsonb),
('comb-a01','{"id":"comb-a01","title":"Two Forbidden Adjacencies","topic":"Combinatorics","level":"Advanced","question":"Eight distinct people sit around a circular table. Two particular people refuse to sit next to each other, and a disjoint particular pair also refuses to sit next to each other. How many seating arrangements are possible?","type":"text","correctAnswer":"2640","hint":"Use inclusion-exclusion. A specified adjacent pair becomes one circular block, with two possible internal orders.","solution":"There are $7!=5040$ unrestricted circular arrangements. For one forbidden pair, the block count is $2\\cdot6!=1440$. For both pairs adjacent, treat both as blocks: $2^2\\cdot5!=480$. Therefore the valid count is $5040-2(1440)+480=2640$.","points":60,"competition":"AIME","answerMode":"numeric-grid","answerDigits":4,"maxAttempts":3,"estimatedSteps":4,"abstraction":3}'::jsonb),
('comb-o01','{"id":"comb-o01","title":"A Constrained Lattice Walk","topic":"Combinatorics","level":"Olympiad","question":"A path from $(0,0)$ to $(10,10)$ uses only steps east and north, never goes above the line $y=x$, and does not pass through $(5,5)$. What is the remainder when the number of such paths is divided by $1000$?","type":"text","correctAnswer":"32","hint":"The paths staying below the diagonal are counted by Catalan numbers. Subtract the paths that pass through $(5,5)$.","solution":"The total number of paths never above $y=x$ is the Catalan number $C_{10}=\\frac{1}{11}\\binom{20}{10}=16796$. Paths through $(5,5)$ split into two independently constrained halves, giving $C_5^2=42^2=1764$. Thus there are $16796-1764=15032$ paths, whose remainder modulo $1000$ is $32$.","points":86,"competition":"AIME","answerMode":"numeric-grid","proOnly":false,"maxAttempts":3,"estimatedSteps":6,"abstraction":5,"answerDigits":3}'::jsonb),
('num-f01','{"id":"num-f01","title":"A Long Power, Reduced","topic":"Number Theory","level":"Foundation","question":"Find the remainder when $7^{2026}$ is divided by $1000$.","type":"text","correctAnswer":"649","hint":"The Carmichael period of units modulo $1000$ divides $100$. Reduce the exponent, then use repeated squaring.","solution":"Since $7^{100}\\equiv1\\pmod{1000}$, reduce $2026$ to $26$. Repeated squaring gives $7^{16}\\equiv601$, $7^8\\equiv801$, and $7^2=49\\pmod{1000}$. Therefore $7^{26}\\equiv601\\cdot801\\cdot49\\equiv649\\pmod{1000}$.","points":57,"competition":"AMC","answerMode":"choice","maxAttempts":3,"estimatedSteps":4,"abstraction":3,"options":["646","648","649","651","654"]}'::jsonb),
('num-a01','{"id":"num-a01","title":"A Periodic Congruence","topic":"Number Theory","level":"Advanced","question":"How many integers $n$ with $1\\le n\\le1000$ satisfy $n\\equiv2^n\\pmod 7$?","type":"text","correctAnswer":"142","hint":"The condition depends only on $n$ modulo $7$ and the period $3$ of $2^n$ modulo $7$.","solution":"The condition repeats every $\\operatorname{lcm}(7,3)=21$. Testing one period gives the valid residues $n\\equiv11,15,16\\pmod{21}$. There are $47$ complete periods through $987$, contributing $47\\cdot3=141$, and the remaining numbers through $1000$ include $n=998\\equiv11\\pmod{21}$. Hence the answer is $142$.","points":66,"competition":"AIME","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":4}'::jsonb),
('num-o01','{"id":"num-o01","title":"A Modular Power Sum","topic":"Number Theory","level":"Olympiad","question":"Let $S=\\sum_{k=1}^{2026}k^{2026}$. Find the remainder when $S$ is divided by $1000$.","type":"text","correctAnswer":"101","hint":"Work modulo $8$ and $125$. The terms repeat modulo $125$, and the full block of $125$ residues has sum $0$ for this exponent.","solution":"Modulo $8$, every even term vanishes and every odd term is $1$, so $S\\equiv1013\\equiv5\\pmod8$. Modulo $125$, a full block of $125$ consecutive residues sums to $0$ because multiples of 5 contribute zero, while the units form a cyclic group and $2026\\equiv26\\pmod{100}$. Sixteen full blocks vanish, and repeated squaring on the remaining residues $1$ through $26$ gives $S\\equiv101\\pmod{125}$. Since $101\\equiv5\\pmod8$, the Chinese remainder theorem gives $S\\equiv101\\pmod{1000}$.","points":86,"competition":"AIME","answerMode":"numeric-grid","proOnly":false,"maxAttempts":3,"estimatedSteps":6,"abstraction":5,"answerDigits":3}'::jsonb),
('gen-amc-alg-001','{"id":"gen-amc-alg-001","title":"A symmetric pair","topic":"Algebra","level":"Foundation","competition":"AMC","question":"Positive reals $a,b$ satisfy $a+b=5$ and $ab=4$. Find $a^2+b^2$.","type":"multiple-choice","options":["15","17","18","21","24"],"correctAnswer":"17","hint":"Expand $(a+b)^2$ and isolate $a^2+b^2$.","solution":"$a^2+b^2=5^2-2(4)=17$.","points":31,"answerMode":"choice","proOnly":false,"maxAttempts":3,"estimatedSteps":2,"abstraction":1}'::jsonb),
('gen-amc-alg-002','{"id":"gen-amc-alg-002","title":"Reciprocal echoes","topic":"Algebra","level":"Foundation","competition":"AMC","question":"A positive real $x$ satisfies $x+\\frac1x=4$. Find $x^2+\\frac1{x^2}$.","type":"multiple-choice","options":["14","15","18","21","12"],"correctAnswer":"14","hint":"Square the relation and remove the middle term.","solution":"$(x+x^{-1})^2=x^2+2+x^{-2}=4^2$, so the answer is $14$.","points":37,"answerMode":"choice","proOnly":false,"maxAttempts":3,"estimatedSteps":2,"abstraction":2}'::jsonb),
('gen-amc-alg-003','{"id":"gen-amc-alg-003","title":"Power sums in disguise","topic":"Algebra","level":"Foundation","competition":"AMC","question":"Let $r,s$ be roots of $t^2-6t+1=0$. Find the remainder of $r^4+s^4$ modulo $1000$.","type":"multiple-choice","options":["155","158","161","152","154"],"correctAnswer":"154","hint":"Use $S_n=(r+s)S_{n-1}-rsS_{n-2}$ with $S_0=2$.","solution":"The recurrence gives $S_4=1154$, whose final three digits are 154.","points":57,"answerMode":"choice","proOnly":false,"maxAttempts":3,"estimatedSteps":4,"abstraction":3}'::jsonb),
('gen-amc-alg-004','{"id":"gen-amc-alg-004","title":"A sequence with a footprint","topic":"Algebra","level":"Foundation","competition":"AMC","question":"A sequence is defined by $u_n=n^2+2n+1$. Find $u_{11}$.","type":"multiple-choice","options":["148","151","142","144","145"],"correctAnswer":"144","hint":"Substitute the index and keep the quadratic and linear terms separate.","solution":"$u_{11}=11^2+2(11)+1=144$.","points":31,"answerMode":"choice","proOnly":false,"maxAttempts":3,"estimatedSteps":2,"abstraction":1}'::jsonb),
('gen-amc-alg-005','{"id":"gen-amc-alg-005","title":"Three variables, one invariant","topic":"Algebra","level":"Foundation","competition":"AMC","question":"If $x+y+z=11$ and $xy+yz+zx=12$, find $x^2+y^2+z^2$.","type":"multiple-choice","options":["104","95","97","98","101"],"correctAnswer":"97","hint":"Expand $(x+y+z)^2$ and compare the cross terms.","solution":"$x^2+y^2+z^2=11^2-2(12)=97$.","points":37,"answerMode":"choice","proOnly":false,"maxAttempts":3,"estimatedSteps":2,"abstraction":2}'::jsonb),
('gen-amc-alg-006','{"id":"gen-amc-alg-006","title":"Evaluate without expanding blindly","topic":"Algebra","level":"Foundation","competition":"AMC","question":"Find $P(2)$ for $P(t)=t^3+7t^2-8t+1$.","type":"multiple-choice","options":["19","21","22","25","28"],"correctAnswer":"21","hint":"Evaluate each power at the requested input before combining terms.","solution":"$P(2)=21$ after substitution.","points":44,"answerMode":"choice","proOnly":false,"maxAttempts":3,"estimatedSteps":3,"abstraction":2}'::jsonb),
('gen-amc-alg-007','{"id":"gen-amc-alg-007","title":"A telescoping square sum","topic":"Algebra","level":"Foundation","competition":"AMC","question":"Find $\\sum_{k=1}^{8}(2k-1)$.","type":"multiple-choice","options":["64","65","68","71","62"],"correctAnswer":"64","hint":"Recognize consecutive square differences.","solution":"$2k-1=k^2-(k-1)^2$, so the sum telescopes to $64$.","points":37,"answerMode":"choice","proOnly":false,"maxAttempts":3,"estimatedSteps":2,"abstraction":2}'::jsonb),
('gen-amc-geo-008','{"id":"gen-amc-geo-008","title":"Heron, carefully","topic":"Geometry","level":"Foundation","competition":"AMC","question":"A triangle has side lengths 13, 14, 15. Find its area.","type":"multiple-choice","options":["85","88","91","82","84"],"correctAnswer":"84","hint":"Use Heron’s formula with the semiperimeter.","solution":"Heron’s formula gives area 84.","points":46,"answerMode":"choice","proOnly":false,"maxAttempts":3,"figure":{"kind":"triangle","labels":["13","14","15"],"values":[13,14,15]},"estimatedSteps":3,"abstraction":2}'::jsonb),
('gen-amc-geo-009','{"id":"gen-amc-geo-009","title":"A cyclic quadrilateral","topic":"Geometry","level":"Foundation","competition":"AMC","question":"A cyclic quadrilateral has sides $3,4,5,6$. Find the square of its area.","type":"multiple-choice","options":["364","367","358","360","361"],"correctAnswer":"360","hint":"Use Brahmagupta’s formula with the semiperimeter.","solution":"$K^2=360$.","points":52,"answerMode":"choice","proOnly":false,"maxAttempts":3,"figure":{"kind":"quadrilateral","labels":["3","4","5","6"],"values":[3,4,5,6]},"estimatedSteps":3,"abstraction":3}'::jsonb),
('gen-amc-geo-010','{"id":"gen-amc-geo-010","title":"Altitude from area","topic":"Geometry","level":"Foundation","competition":"AMC","question":"A right triangle has legs 8 and 15, with hypotenuse 17. Write the altitude as a reduced fraction and find its numerator.","type":"multiple-choice","options":["127","118","120","121","124"],"correctAnswer":"120","hint":"Compute the area in two ways, then reduce the fraction.","solution":"Equating the two area formulas gives altitude $120/17=120/17$. Its numerator is 120.","points":46,"answerMode":"choice","proOnly":false,"maxAttempts":3,"figure":{"kind":"triangle","labels":["8","15","17"],"values":[8,15,17]},"estimatedSteps":3,"abstraction":2}'::jsonb),
('gen-amc-geo-011','{"id":"gen-amc-geo-011","title":"Coordinates with area","topic":"Geometry","level":"Foundation","competition":"AMC","question":"The vertices are $(0,0)$, $(8,0)$, $(10,4)$, and $(2,6)$. Find the area.","type":"multiple-choice","options":["40","42","43","46","49"],"correctAnswer":"42","hint":"Apply the shoelace formula.","solution":"The shoelace sum gives area 42.","points":59,"answerMode":"choice","proOnly":false,"maxAttempts":3,"figure":{"kind":"coordinate-grid","labels":["(0,0)","(8,0)","(10,4)","(2,6)"],"values":[0,0,8,0,10,4,2,6]},"estimatedSteps":4,"abstraction":3}'::jsonb),
('gen-amc-geo-012','{"id":"gen-amc-geo-012","title":"A circle in disguise","topic":"Geometry","level":"Foundation","competition":"AMC","question":"A circle has circumference $16\\pi$. Find its area divided by $\\pi$.","type":"multiple-choice","options":["64","65","68","71","62"],"correctAnswer":"64","hint":"Recover the radius from $C=2\\pi r$.","solution":"The radius is 8, so area divided by pi is 64.","points":33,"answerMode":"choice","proOnly":false,"maxAttempts":3,"figure":{"kind":"circle","labels":["r=8"],"values":[8]},"estimatedSteps":2,"abstraction":1}'::jsonb),
('gen-amc-geo-013','{"id":"gen-amc-geo-013","title":"Similarity carries the length","topic":"Geometry","level":"Foundation","competition":"AMC","question":"Two equilateral triangles have side ratio $1:4$. If the smaller side is 4, find the larger side.","type":"multiple-choice","options":["17","20","23","14","16"],"correctAnswer":"16","hint":"Multiply by the scale factor once.","solution":"The larger side is 4 times 4, or 16.","points":39,"answerMode":"choice","proOnly":false,"maxAttempts":3,"figure":{"kind":"triangle","labels":["4","4","4"],"values":[4,4,4]},"estimatedSteps":2,"abstraction":2}'::jsonb),
('gen-amc-geo-014','{"id":"gen-amc-geo-014","title":"A regular hexagon","topic":"Geometry","level":"Foundation","competition":"AMC","question":"A regular hexagon has side 8. Find its area divided by $\\sqrt3$.","type":"multiple-choice","options":["100","103","94","96","97"],"correctAnswer":"96","hint":"Split the hexagon into six equilateral triangles.","solution":"$K=6(\\sqrt3/4)8^2$, so $K/\\sqrt3=96$.","points":46,"answerMode":"choice","proOnly":false,"maxAttempts":3,"figure":{"kind":"regular-polygon","values":[8,6],"labels":["8","8","8","8","8","8"]},"estimatedSteps":3,"abstraction":2}'::jsonb),
('gen-amc-com-015','{"id":"gen-amc-com-015","title":"Choose without order","topic":"Combinatorics","level":"Foundation","competition":"AMC","question":"How many 2-person teams can be chosen from 8 distinct people?","type":"multiple-choice","options":["35","26","28","29","32"],"correctAnswer":"28","hint":"Use a binomial coefficient.","solution":"$\\binom{8}{2}=28$.","points":31,"answerMode":"choice","proOnly":false,"maxAttempts":3,"estimatedSteps":2,"abstraction":1}'::jsonb),
('gen-amc-com-016','{"id":"gen-amc-com-016","title":"Binary strings with breathing room","topic":"Combinatorics","level":"Foundation","competition":"AMC","question":"How many binary strings of length 9 contain no two consecutive $1$s?","type":"multiple-choice","options":["87","89","90","93","96"],"correctAnswer":"89","hint":"Split by the first symbol; the recurrence is Fibonacci-like.","solution":"The recurrence $F_n=F_{n-1}+F_{n-2}$ gives 89.","points":50,"answerMode":"choice","proOnly":false,"maxAttempts":3,"estimatedSteps":3,"abstraction":3}'::jsonb),
('gen-amc-com-017','{"id":"gen-amc-com-017","title":"A circular block","topic":"Combinatorics","level":"Foundation","competition":"AMC","question":"8 distinct people sit around a circle, with two specified people together. Find the count modulo $1000$.","type":"multiple-choice","options":["440","441","444","447","438"],"correctAnswer":"440","hint":"Treat the pair as one block with two orientations.","solution":"The count is $2(6)!=1440$, giving remainder 440.","points":44,"answerMode":"choice","proOnly":false,"maxAttempts":3,"estimatedSteps":3,"abstraction":2}'::jsonb),
('gen-amc-com-018','{"id":"gen-amc-com-018","title":"A diagonal boundary","topic":"Combinatorics","level":"Foundation","competition":"AMC","question":"How many paths from $(0,0)$ to $(7,7)$ using east and north steps never go above $y=x$?","type":"multiple-choice","options":["430","433","436","427","429"],"correctAnswer":"429","hint":"This is the Catalan number $C_n$.","solution":"$C_7=429$.","points":50,"answerMode":"choice","proOnly":false,"maxAttempts":3,"estimatedSteps":3,"abstraction":3}'::jsonb),
('gen-amc-com-019','{"id":"gen-amc-com-019","title":"Distinct digits, one residue","topic":"Combinatorics","level":"Foundation","competition":"AMC","question":"How many 4-digit integers have distinct digits and are divisible by $3$?","type":"multiple-choice","options":["1552","1555","1546","1548","1549"],"correctAnswer":"1548","hint":"Group digit sets by their sum modulo 3 and handle a leading zero separately.","solution":"Enumerating residue-compatible digit sets and valid leading digits gives 1548.","points":70,"answerMode":"choice","proOnly":false,"maxAttempts":3,"estimatedSteps":5,"abstraction":4}'::jsonb),
('gen-amc-com-020','{"id":"gen-amc-com-020","title":"Inclusion–exclusion in a crowd","topic":"Combinatorics","level":"Foundation","competition":"AMC","question":"How many integers from $1$ through 615 are divisible by 4 or 8?","type":"multiple-choice","options":["160","151","153","154","157"],"correctAnswer":"153","hint":"Add both multiples and subtract the overlap.","solution":"The inclusion–exclusion count is 153.","points":44,"answerMode":"choice","proOnly":false,"maxAttempts":3,"estimatedSteps":3,"abstraction":2}'::jsonb),
('gen-amc-com-021','{"id":"gen-amc-com-021","title":"Unordered triples","topic":"Combinatorics","level":"Foundation","competition":"AMC","question":"How many subsets of size 3 can be selected from 8 labelled objects?","type":"multiple-choice","options":["54","56","57","60","63"],"correctAnswer":"56","hint":"Divide ordered selections by $3!$.","solution":"$\\binom{8}{3}=56$.","points":31,"answerMode":"choice","proOnly":false,"maxAttempts":3,"estimatedSteps":2,"abstraction":1}'::jsonb),
('gen-amc-num-022','{"id":"gen-amc-num-022","title":"A long power, reduced","topic":"Number Theory","level":"Foundation","competition":"AMC","question":"Find the remainder when $3^{2026}$ is divided by $1000$.","type":"multiple-choice","options":["329","330","333","336","327"],"correctAnswer":"329","hint":"Reduce the exponent with a period, then use repeated squaring.","solution":"$3^{2026}\\equiv329\\pmod{1000}$.","points":57,"answerMode":"choice","proOnly":false,"maxAttempts":3,"estimatedSteps":4,"abstraction":3}'::jsonb),
('gen-amc-num-023','{"id":"gen-amc-num-023","title":"Coprime choices","topic":"Number Theory","level":"Foundation","competition":"AMC","question":"How many positive integers less than 60 are coprime to 60?","type":"multiple-choice","options":["17","20","23","14","16"],"correctAnswer":"16","hint":"Use Euler’s product over distinct prime factors.","solution":"$\\varphi(60)=16$.","points":44,"answerMode":"choice","proOnly":false,"maxAttempts":3,"estimatedSteps":3,"abstraction":2}'::jsonb),
('gen-amc-num-024','{"id":"gen-amc-num-024","title":"Counting divisors by exponents","topic":"Number Theory","level":"Foundation","competition":"AMC","question":"How many positive divisors does $121500$ have?","type":"multiple-choice","options":["76","79","70","72","73"],"correctAnswer":"72","hint":"Factor the number and multiply one more than each exponent.","solution":"$121500=2^{2}3^{5}5^{3}$, so the count is 72.","points":44,"answerMode":"choice","proOnly":false,"maxAttempts":3,"estimatedSteps":3,"abstraction":2}'::jsonb),
('gen-amc-num-025','{"id":"gen-amc-num-025","title":"A periodic congruence","topic":"Number Theory","level":"Foundation","competition":"AMC","question":"How many integers $n$ with $1\\le n\\le511$ satisfy $n\\equiv2^n\\pmod7$?","type":"multiple-choice","options":["79","70","72","73","76"],"correctAnswer":"72","hint":"The condition repeats with period $\\operatorname{lcm}(7,3)=21$.","solution":"The valid residues in one period are 11, 15, and 16; counting them through 511 gives 72.","points":63,"answerMode":"choice","proOnly":false,"maxAttempts":3,"estimatedSteps":4,"abstraction":4}'::jsonb),
('gen-amc-num-026','{"id":"gen-amc-num-026","title":"Two clocks, one residue","topic":"Number Theory","level":"Foundation","competition":"AMC","question":"Find the least nonnegative $x$ with $x\\equiv1\\pmod{5}$ and $x\\equiv7\\pmod{11}$.","type":"multiple-choice","options":["49","51","52","55","58"],"correctAnswer":"51","hint":"Substitute the first congruence into the second.","solution":"The least compatible residue is 51.","points":63,"answerMode":"choice","proOnly":false,"maxAttempts":3,"estimatedSteps":4,"abstraction":4}'::jsonb),
('gen-amc-num-027','{"id":"gen-amc-num-027","title":"Powers of five inside a factorial","topic":"Number Theory","level":"Foundation","competition":"AMC","question":"Find the exponent of $5$ in the prime factorization of $45!$.","type":"multiple-choice","options":["10","11","14","17","8"],"correctAnswer":"10","hint":"Add the quotients by 5, 25, 125, and so on.","solution":"Legendre’s formula gives exponent 10.","points":44,"answerMode":"choice","proOnly":false,"maxAttempts":3,"estimatedSteps":3,"abstraction":2}'::jsonb),
('gen-amc-num-028','{"id":"gen-amc-num-028","title":"The exponent returns","topic":"Number Theory","level":"Foundation","competition":"AMC","question":"Find $3^{802}$ modulo 1000.","type":"multiple-choice","options":["10","13","16","7","9"],"correctAnswer":"9","hint":"Use the period of 3 modulo 1000.","solution":"$3^{100}\\equiv1\\pmod{1000}$, so the remainder is $9$.","points":50,"answerMode":"choice","proOnly":false,"maxAttempts":3,"estimatedSteps":3,"abstraction":3}'::jsonb),
('gen-aime-alg-001','{"id":"gen-aime-alg-001","title":"A symmetric pair","topic":"Algebra","level":"Advanced","competition":"AIME","question":"Positive reals $a,b$ satisfy $a+b=6$ and $ab=5$. Find $a^2+b^2$.","type":"text","correctAnswer":"026","hint":"Expand $(a+b)^2$ and isolate $a^2+b^2$.","solution":"$a^2+b^2=6^2-2(5)=26$.","points":34,"answerMode":"numeric-grid","answerDigits":3,"proOnly":false,"maxAttempts":3,"estimatedSteps":2,"abstraction":1}'::jsonb),
