('gen-aime-num-024','{"id":"gen-aime-num-024","title":"Counting divisors by exponents","topic":"Number Theory","level":"Advanced","competition":"AIME","question":"How many positive divisors does $9720$ have?","type":"text","correctAnswer":"048","hint":"Factor the number and multiply one more than each exponent.","solution":"$9720=2^{3}3^{5}5^{1}$, so the count is 48.","points":47,"answerMode":"numeric-grid","answerDigits":3,"proOnly":false,"maxAttempts":3,"estimatedSteps":3,"abstraction":2}'::jsonb),
('gen-aime-num-025','{"id":"gen-aime-num-025","title":"A periodic congruence","topic":"Number Theory","level":"Advanced","competition":"AIME","question":"How many integers $n$ with $1\\le n\\le548$ satisfy $n\\equiv2^n\\pmod7$?","type":"text","correctAnswer":"078","hint":"The condition repeats with period $\\operatorname{lcm}(7,3)=21$.","solution":"The valid residues in one period are 11, 15, and 16; counting them through 548 gives 78.","points":66,"answerMode":"numeric-grid","answerDigits":3,"proOnly":false,"maxAttempts":3,"estimatedSteps":4,"abstraction":4}'::jsonb),
